clear; clc; close all;

%% ------------------------------------------------------------------------
% PRIVALOMA UŽDUOTIS (6 balai)
% -------------------------------------------------------------------------

% 7. Komandų surinkimas pagal 1 pav. pavyzdį
x = 1:32;
y = x.^2;

figure; %[output:21cd2598]
plot(x, y, 'o-r', x, y/3, 'xb') %[output:21cd2598]
title('Dvi funkcijos') %[output:21cd2598]
xlabel('X-ai') %[output:21cd2598]
ylabel('F_1 [-o-] | F_2 [-x-]') %[output:21cd2598]

% 8. Pagalbos paieškos būdai MATLAB aplinkoje:
% - Komandiniame lange įvedus: help sin (parodo trumpą aprašymą).
% - Komandiniame lange įvedus: doc plot (atidaro išsamią dokumentaciją).
% - Naudojant viršutinį paieškos laukelį (Help / Search Documentation).

% 9. Funkcijų sintaksės ir argumentų paaiškinimas:
%
% A) linspace(x1, x2, n)
%    - Paskirtis: generuoja n tolygiai išdėstytų skaičių tarp x1 ir x2.
%    - Įvesties argumentai: x1 (pradžia), x2 (pabaiga), n (taškų skaičius; jei nenurodyta, default = 100).
%    - Išvesties argumentas: eilutės vektorius.
%
% B) size(A)
%    - Paskirtis: grąžina matricos A matmenis (eilučių ir stulpelių skaičių).
%    - Įvesties argumentai: matrica A (galima nurodyti ir dimensiją: size(A, 1)).
%    - Išvesties argumentai: vektorius [eilutės, stulpeliai].
%
% C) max(A)
%    - Paskirtis: randa didžiausią reikšmę.
%    - Įvesties argumentai: vektorius arba matrica A.
%    - Išvesties argumentai: [M, I] = max(A) -> M (didžiausia reikšmė), I (indeksas).


%% ------------------------------------------------------------------------
% PAPILDOMA UŽDUOTIS (4 balai)
% -------------------------------------------------------------------------

% 1. Kintamasis N - paskutinis studento ID skaitmuo
N = 9; 

% 2. Vektoriaus kūrimas: pirmas elem. (N+1), paskutinis (N+4), žingsnis 0.5
v = (N + 1) : 0.5 : (N + 4);

% 3. 3x3 matrica A (pirmas elem. N, kiti didėja vienetu)
A = [N,     N + 1, N + 2;
    N + 3, N + 4, N + 5;
    N + 6, N + 7, N + 8];

% 4. Elementų atrinkimas pagal pateiktas schemas:
% a) Schema a: atrinkti 3-os eilutės 2-ąjį stulpelį
A_a = A(3, 2);

% b) Schema b: atrinkti 2-3 eilutes ir 1-2 stulpelius
A_b = A(2:3, 1:2);

% c) Schema c: atrinkti 1 bei 3 eilutes ir 1 bei 3 stulpelius
A_c = A([1, 3], [1, 3]);

% 5. Vektoriaus v prijungimas prie matricos A:
% Kadangi matrica A yra 3x3, o vektorius v turi 7 elementus, 
% paimame pirmus 3 vektoriaus elementus ir prijungiame kaip naują eilutę:
v_mod = v(1:3);
A_prijungta = [A; v_mod]; % Prijungiama 4-oji eilutė

% Rezultatų išvedimas į komandinį langą patikrinimui
disp('--- Matrica A ---'); %[output:999002d7]
disp(A); %[output:55092316]
disp('--- Schemos a rezultatai ---'); %[output:669293e5]
disp(A_a); %[output:08188df6]
disp('--- Schemos b rezultatai ---'); %[output:2ec4ff15]
disp(A_b); %[output:2dbdf9e8]
disp('--- Schemos c rezultatai ---'); %[output:0a780c96]
disp(A_c); %[output:76a3e18f]
disp('--- Matrica A su prijungta nauja eilute ---'); %[output:577afa1b]
disp(A_prijungta); %[output:85bcd29c]

